// Scene graph builders.
// Each export returns a plain-data Scene Graph v1 object that the renderer
// can consume.  No Three.js imports here — scenes are pure data so they can
// be serialised, validated, or eventually generated by an LLM.

export function createImpactSceneGraph(seed, palette) {
    return {
        version: 1,
        duration: 10,
        world: {
            environment: 'space',
            timeScale: 1,
            physicsMode: 'plausible'
        },
        objects: [
            {
                id: 'earth',
                type: 'sphere',
                role: 'planet',
                position: [0, 0, 0],
                radius: 12,
                material: {
                    preset: 'earthlike',
                    color: palette[0],
                    atmosphere: true
                }
            },
            {
                id: 'comet',
                type: 'projectile',
                role: 'comet',
                radius: 1.25,
                start: [52, 25, -48],
                end: [8.8, 5.6, -6.4],
                impactAt: 4.2,
                material: {
                    preset: 'ice_glow',
                    color: '#dff7ff'
                },
                trail: {
                    enabled: true,
                    length: 42,
                    color: palette[2] || '#ffb454'
                }
            }
        ],
        events: [
            {
                id: 'impact',
                type: 'collision',
                source: 'comet',
                target: 'earth',
                at: 4.2,
                position: [8.8, 5.6, -6.4],
                effects: ['flash', 'shockwave', 'debris']
            }
        ],
        effects: [
            { id: 'flash', type: 'flash', event: 'impact', color: palette[2] || '#ffb454', duration: 0.85 },
            { id: 'shockwave', type: 'shockwave', event: 'impact', color: palette[2] || '#ffb454', duration: 3.4, maxRadius: 24 },
            { id: 'debris', type: 'debris', event: 'impact', color: palette[3] || '#ff5b45', count: 480 }
        ],
        camera: {
            mode: 'cinematic_orbit',
            focus: 'earth',
            distance: 58,
            shakeAt: 4.2
        },
        seed
    };
}

// --- Binary star: FIXED ----------------------------------------------------
//
// Previous version used two fuzzy `particle_cloud` blobs plus a vertical
// sinusoid on the orbit, which made it look like wandering smoke. New
// version uses dedicated `star_body` objects (dense Fibonacci core + soft
// corona) and a proper `binary_orbit` motion that keeps both stars in a
// shared plane around the barycenter at [0, 0, 0].
export function createBinaryStarSceneGraph(seed, palette) {
    return {
        version: 1,
        duration: 14,
        world: { environment: 'space', timeScale: 1, physicsMode: 'plausible' },
        objects: [
            {
                id: 'star_a',
                type: 'star_body',
                role: 'star',
                radius: 4.6,
                massRatio: 1.0,
                material: {
                    color: palette[0] || '#ffcf6b',
                    corona: '#ffe3a3',
                    coronaRadius: 9.5
                }
            },
            {
                id: 'star_b',
                type: 'star_body',
                role: 'star',
                radius: 3.4,
                massRatio: 1.6, // star B is lighter ⇒ sits farther from barycenter
                material: {
                    color: palette[1] || '#78a6ff',
                    corona: '#c6dcff',
                    coronaRadius: 7.5
                }
            },
            {
                id: 'barycenter_mark',
                type: 'glow_point',
                role: 'barycenter',
                radius: 0.5,
                material: { color: palette[2] || '#f5f7fb' }
            }
        ],
        motions: [
            {
                type: 'binary_orbit',
                targets: ['star_a', 'star_b'],
                semiMajor: 18,
                speed: 0.52,
                tilt: 0.12
            }
        ],
        forces: [],
        effects: [
            { id: 'starfield', type: 'starfield', count: 600, color: '#f5f7fb', radius: 80 }
        ],
        events: [],
        camera: { mode: 'free_orbit', distance: 62 },
        seed
    };
}

