// --- Speeding car: FIXED ---------------------------------------------------
//
// Previous version baked body + glass + lights + 4 wheels into a single
// Points buffer, so the wheels couldn't actually rotate. New version splits
// each part into its own object and attaches `spin` motions to the wheels —
// chassis and cabin remain static while wheels rotate around their local Z.
export function createSpeedingCarSceneGraph(seed, palette, dense = false) {
    const wheelOffset = 4.45;
    const wheelY = -0.85;
    const wheelRadius = 1.55;
    const wheelCount = dense ? 360 : 240;
    const spinSpeed = 8;

    const wheels = [
        { id: 'wheel_fl', position: [-8, wheelY, -wheelOffset] },
        { id: 'wheel_fr', position: [-8, wheelY,  wheelOffset] },
        { id: 'wheel_rl', position: [ 8, wheelY, -wheelOffset] },
        { id: 'wheel_rr', position: [ 8, wheelY,  wheelOffset] }
    ];

    return {
        version: 1,
        duration: 12,
        world: { environment: 'highway', timeScale: 1, physicsMode: 'plausible' },
        objects: [
            {
                id: 'car_chassis',
                type: 'car_part',
                preset: 'chassis',
                role: 'vehicle',
                position: [0, -1.5, 0],
                particleCount: dense ? 2600 : 2000,
                material: { color: palette[0] || '#4fd8ff' }
            },
            {
                id: 'car_cabin',
                type: 'car_part',
                preset: 'cabin',
                position: [-2.4, 3.6, 0],
                particleCount: dense ? 900 : 700,
                material: { color: '#d9f6ff' }
            },
            {
                id: 'car_front_light',
                type: 'car_part',
                preset: 'front_light',
                position: [12.2, 0.7, 0],
                particleCount: 160,
                material: { color: palette[2] || '#ffcf6b' }
            },
            {
                id: 'car_tail_light',
                type: 'car_part',
                preset: 'tail_light',
                position: [-13.2, 0.5, 0],
                particleCount: 160,
                material: { color: palette[3] || '#ff4f6d' }
            },
            ...wheels.map((w) => ({
                id: w.id,
                type: 'wheel',
                role: 'wheel',
                position: [w.position[0], w.position[1] - 1.5, w.position[2]],
                radius: wheelRadius,
                particleCount: wheelCount,
                material: { tyre: '#1a1d22', rim: '#9aa6b8', spokes: '#f5f7fb' }
            })),
            {
                id: 'highway',
                type: 'particle_shape',
                preset: 'highway',
                role: 'road',
                position: [0, -7, 0],
                particleCount: dense ? 1700 : 1200,
                material: {
                    asphalt: '#384150',
                    lane: '#f5f7fb',
                    edge: '#45d7ff'
                }
            }
        ],
        motions: [
            { type: 'speed_pulse', target: 'car_chassis', amplitude: 0.16, speed: 5.2 },
            { type: 'speed_pulse', target: 'car_cabin', amplitude: 0.16, speed: 5.2 },
            ...wheels.map((w) => ({
                type: 'spin',
                target: w.id,
                axis: 'z',
                speed: spinSpeed
            })),
            ...wheels.map((w) => ({
                type: 'speed_pulse',
                target: w.id,
                amplitude: 0.12,
                speed: 5.2
            })),
            { type: 'road_scroll', target: 'highway', speed: 1.15, length: 86 }
        ],
        forces: [],
        effects: [
            {
                id: 'speed_wake',
                type: 'speed_trail',
                target: 'car_chassis',
                color: palette[1] || '#f5f7fb',
                count: dense ? 900 : 620,
                length: 38
            }
        ],
        events: [],
        camera: { mode: 'free_orbit', distance: 44 },
        seed
    };
}

