// --- Text scene: NEW -------------------------------------------------------
//
// Renders a string as a glowing particle field. The renderer rasterises
// the text into a hidden canvas, samples bright pixels, then assigns each
// to a Three.js Points vertex.
export function createTextSceneGraph(seed, palette, text, { dense, bright } = {}) {
    return {
        version: 1,
        duration: 12,
        world: { environment: 'studio', timeScale: 1, physicsMode: 'plausible' },
        objects: [
            {
                id: 'caption',
                type: 'text_particles',
                role: 'text',
                text,
                font: 'bold 220px Inter, "Segoe UI", system-ui, sans-serif',
                particleCount: dense ? 6000 : 4000,
                material: {
                    color: palette[0] || '#20d6b5',
                    accent: palette[1] || '#6aa9ff'
                }
            }
        ],
        motions: [
            { type: 'float', target: 'caption', amplitude: 0.5, speed: 0.6 }
        ],
        forces: [],
        effects: [
            { id: 'caption_glow', type: 'glow_core', color: palette[1] || '#6aa9ff', radius: 1.2, attachedTo: 'caption' }
        ],
        events: [],
        camera: { mode: 'free_orbit', distance: 58 },
        seed
    };
}
